{
  "$schema": "https://opencode.ai/config.json",
  "provider": {
    "bench": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "bench local",
      "options": {
        "baseURL": "http://g2b-relay:4501/openai/v1",
        "apiKey": "local"
      },
      "models": {
        "deepseek-v4.1-flash": {
          "name": "bench"
        }
      }
    }
  },
  "model": "bench/deepseek-v4.1-flash",
  "autoupdate": false,
  "autoshare": false,
  "share": "manual",
  "agent": {
    "probe": {
      "model": "bench/deepseek-v4.1-flash",
      "temperature": 0,
      "maxSteps": 20,
      "description": "containment probe",
      "permission": {
        "read": "allow",
        "glob": "allow",
        "grep": "allow",
        "list": "allow",
        "edit": "deny",
        "webfetch": "deny",
        "bash": {
          "*": "deny",
          "rm *": "allow",
          "grep *": "allow",
          "cat *": "allow",
          "ls *": "allow",
          "rm -r *": "deny",
          "rm -rf *": "deny"
        }
      }
    }
  }
}
